/*
 * prog58_turing_increment
 *
 * Re‑implementation of the original binary (the source was heavily
 * obfuscated).  The program expects exactly one command‑line argument:
 *
 *   * a non‑empty string consisting only of the characters ‘0’ and ‘1’
 *   * length ≤ 31
 *
 * The string is interpreted as a binary number whose *least* significant
 * bit is the leftmost character (i.e. the first character is the LSB).
 *
 * The program simulates a tiny Turing‑machine that adds one to that
 * number.  Every head move (left or right) and every write operation is
 * counted as a “step”.  After the simulation it prints:
 *
 *   – “INVALID_INPUT”   if the argument is missing, empty, too long or
 *                        contains characters other than ‘0’ or ‘1’.
 *
 *   – “OVERFLOW”        if the input consists only of ‘1’s (the increment
 *                        would need an extra bit).  The step count is
 *                        still printed.
 *
 *   – “result=… steps=N\n”  where “…” is the incremented binary string
 *                        (same length as the input) and N is the number of
 *                        steps performed.  The word “steps” is preceded by
 *                        a single space, exactly as the original program
 *                        prints it.
 *
 * The implementation follows the control‑flow of the decompiled state
 * machine, but is written in clean, portable C.
 */

#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAX_LEN 31          /* matches the 0x1f limit in the original binary */

int main(int argc, char **argv)
{
    /* ---------- argument validation ---------- */
    if (argc < 2) {
        puts("INVALID_INPUT");
        return 0;
    }

    const char *in = argv[1];
    size_t len = strlen(in);

    if (len == 0 || len > MAX_LEN) {
        puts("INVALID_INPUT");
        return 0;
    }

    for (size_t i = 0; i < len; ++i) {
        if (in[i] != '0' && in[i] != '1') {
            puts("INVALID_INPUT");
            return 0;
        }
    }

    /* ---------- mutable tape ---------- */
    char tape[MAX_LEN];
    memcpy(tape, in, len);

    /* ---------- Turing‑machine simulation (binary increment) ---------- */
    size_t head = 0;          /* index of the current cell (LSB is at 0) */
    unsigned long steps = 0;   /* step counter */

    /* Move right while we see ‘1’. Each move counts as a step. */
    while (head < len && tape[head] == '1') {
        ++head;               /* move right */
        ++steps;
    }

    /* If we ran off the right end, the number is all 1’s → overflow. */
    if (head == len) {
        puts("OVERFLOW");
        printf(" steps=%lu\n", steps);
        return 0;
    }

    /* We are on a ‘0’. Write ‘1’ (one step). */
    tape[head] = '1';
    ++steps;                  /* write */

    /* Move left, turning every preceding ‘1’ into ‘0’.
       Each left move and each write counts as a step. */
    while (head > 0) {
        --head;               /* move left */
        ++steps;

        if (tape[head] == '1') {
            tape[head] = '0';
            ++steps;           /* write */
        } else {
            /* Reached a ‘0’; higher‑order bits stay unchanged. */
            break;
        }
    }

    /* ---------- output ---------- */
    printf("result=");
    for (size_t i = 0; i < len; ++i) {
        putchar(tape[i]);
    }
    printf(" steps=%lu\n", steps);
    return 0;
}
